const http=require('http'),fs=require('fs'),crypto=require('crypto');
const dir=process.env.DATA_DIR||'/data';fs.mkdirSync(dir,{recursive:true});
const page=fs.readFileSync(__dirname+'/index.html');
function send(res,n,data){res.writeHead(n,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(data))}
http.createServer(async(req,res)=>{
try{
const url=new URL(req.url,'http://localhost');
if(url.pathname==='/health')return send(res,200,{ok:true});
if(url.pathname==='/api/boards'&&req.method==='POST'){
const id=crypto.randomBytes(18).toString('hex');fs.writeFileSync(dir+'/'+id+'.json',JSON.stringify({name:'Our study board',tasks:[]}));return send(res,201,{id});
}
const m=url.pathname.match(/^\/api\/boards\/([a-f0-9]{36})(?:\/tasks(?:\/([a-f0-9-]{36}))?)?$/);
if(m){
const file=dir+'/'+m[1]+'.json';if(!fs.existsSync(file))return send(res,404,{error:'Board not found'});
if(req.method==='GET')return send(res,200,JSON.parse(fs.readFileSync(file)));
let body='';for await(const chunk of req){body+=chunk;if(body.length>20000)return send(res,413,{error:'Task is too large'});}
let input={};try{input=body?JSON.parse(body):{}}catch{return send(res,400,{error:'Invalid data'})}
const board=JSON.parse(fs.readFileSync(file));
if(req.method==='POST'&&url.pathname.endsWith('/tasks')){
if(typeof input.title!=='string'||!input.title.trim())return send(res,400,{error:'Add a task title'});
board.tasks.push({id:crypto.randomUUID(),title:input.title.trim().slice(0,160),subject:String(input.subject||'General').slice(0,40),assignee:String(input.assignee||'').slice(0,60),due:/^\d{4}-\d{2}-\d{2}$/.test(input.due)?input.due:'',status:'todo'});
}else if(m[2]&&req.method==='PATCH'){
const task=board.tasks.find(t=>t.id===m[2]);if(!task)return send(res,404,{error:'Task not found'});
if(!['todo','doing','done'].includes(input.status))return send(res,400,{error:'Invalid status'});task.status=input.status;
}else if(m[2]&&req.method==='DELETE'){board.tasks=board.tasks.filter(t=>t.id!==m[2]);}
else return send(res,405,{error:'Method not allowed'});
fs.writeFileSync(file+'.tmp',JSON.stringify(board));fs.renameSync(file+'.tmp',file);return send(res,200,board);
}
if(req.method==='GET'&&(url.pathname==='/'||/^\/b\/[a-f0-9]{36}$/.test(url.pathname))){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'});return res.end(page)}
send(res,404,{error:'Not found'});
}catch(e){console.error(e);send(res,500,{error:'Could not save. Please try again.'})}
}).listen(3000,'0.0.0.0',()=>console.log('Classboard listening on port 3000'));

